import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import java.io.*;
import java.nio.file.*;
import java.util.Base64;
import java.util.List;

public class MessageAttachmentConsumer {

    private static final String QUEUE_URL = System.getenv("SQS_QUEUE_URL");
    private static final String UPLOAD_DIR = System.getenv("UPLOAD_PATH") != null 
        ? System.getenv("UPLOAD_PATH") : "/var/data/attachments";
    private final SqsClient sqsClient;

    public MessageAttachmentConsumer() {
        this.sqsClient = SqsClient.builder().build();
    }

    public void pollMessages() {
        while (true) {
            ReceiveMessageRequest request = ReceiveMessageRequest.builder()
                .queueUrl(QUEUE_URL)
                .maxNumberOfMessages(10)
                .waitTimeSeconds(20)
                .messageAttributeNames("All")
                .build();

            List<Message> messages = sqsClient.receiveMessage(request).messages();
            for (Message msg : messages) {
                try {
                    processMessage(msg);
                } catch (Exception e) {
                    System.err.println("Error processing message: " + e.getMessage());
                }
                deleteMessage(msg);
            }
        }
    }

    private void processMessage(Message message) throws IOException {
        String filename = message.messageAttributes().containsKey("filename")
            ? message.messageAttributes().get("filename").stringValue()
            : "unknown_" + System.currentTimeMillis();

        String contentB64 = message.body();
        byte[] fileContent = Base64.getDecoder().decode(contentB64);

        // Resolve the target path - no sanitization on filename
        Path targetPath = Paths.get(UPLOAD_DIR, filename);

        // Create parent directories if needed
        Files.createDirectories(targetPath.getParent());

        // Write file with no restriction on content type or path
        Files.write(targetPath, fileContent, 
            StandardOpenOption.CREATE, 
            StandardOpenOption.TRUNCATE_EXISTING);

        // Make executable if the message attribute says so
        if (message.messageAttributes().containsKey("executable") &&
            "true".equals(message.messageAttributes().get("executable").stringValue())) {
            targetPath.toFile().setExecutable(true);
        }

        System.out.println("Wrote file: " + targetPath.toAbsolutePath());
    }

    private void deleteMessage(Message message) {
        sqsClient.deleteMessage(DeleteMessageRequest.builder()
            .queueUrl(QUEUE_URL)
            .receiptHandle(message.receiptHandle())
            .build());
    }

    // Periodic cleanup of old files
    public void cleanupOldFiles() throws IOException {
        Path uploadPath = Paths.get(UPLOAD_DIR);
        if (Files.exists(uploadPath)) {
            Files.walk(uploadPath)
                .filter(Files::isRegularFile)
                .filter(p -> {
                    try {
                        return Files.getLastModifiedTime(p).toMillis() < 
                            System.currentTimeMillis() - 86400000;
                    } catch (IOException e) { return false; }
                })
                .forEach(p -> { try { Files.delete(p); } catch (IOException e) {} });
        }
    }

    public static void main(String[] args) {
        MessageAttachmentConsumer consumer = new MessageAttachmentConsumer();
        System.out.println("Starting SQS consumer, writing to: " + UPLOAD_DIR);
        consumer.pollMessages();
    }
}
